    pub fn touch_directory_grant(&self, application_id: &str, grant_id: &str) -> StorageResult<()> {
        let conn = self
            .connection
            .lock()
            .map_err(|_| StorageError::Internal("registry lock poisoned".into()))?;
        conn.execute("UPDATE directory_grants SET last_used_at_ms=?1 WHERE id=?2 AND application_id=?3 AND revoked_at_ms IS NULL", params![now_ms(),grant_id,application_id])?;
        Ok(())
    }

    pub fn revoke_directory_grant(
        &self,
        application_id: &str,
        grant_id: &str,
    ) -> StorageResult<bool> {
        let conn = self
            .connection
            .lock()
            .map_err(|_| StorageError::Internal("registry lock poisoned".into()))?;
        let changed = conn.execute("UPDATE directory_grants SET revoked_at_ms=?1 WHERE id=?2 AND application_id=?3 AND revoked_at_ms IS NULL", params![now_ms(),grant_id,application_id])?;
        Ok(changed > 0)
    }

    pub fn revoke_directory_grant_with_request(
        &self,
        application_id: &str,
        grant_id: &str,
        request_id: &str,
    ) -> StorageResult<bool> {
        validate_request_id(request_id)?;
        validate_opaque_id(application_id)?;
        let fingerprint = semantic_fingerprint(
            "grant-revoke",
            &json!({
                "applicationId":application_id, "destinationId":grant_id
            }),
        )?;
        let mut conn = self
            .connection
            .lock()
            .map_err(|_| StorageError::Internal("registry lock poisoned".into()))?;
        let tx = conn.transaction()?;
        if let Some(previous) =
            sql_atomic_receipt(&tx, true, application_id, request_id, &fingerprint)?
        {
            return Ok(previous);
        }
        ensure_application_exists(&tx, application_id)?;
        let revoked = tx.execute("UPDATE directory_grants SET revoked_at_ms=?1 WHERE id=?2 AND application_id=?3 AND revoked_at_ms IS NULL",
            params![now_ms(),grant_id,application_id])? > 0;
        sql_atomic_store(
            &tx,
            true,
            application_id,
            request_id,
            "grant-revoke",
            &fingerprint,
            &revoked,
        )?;
        tx.commit()?;
        Ok(revoked)
    }

